const INDEX = new Map<string, number>(ROUTE_ANCHORS.map((a, i) => [a.id, i] as const));

/** 两个锚点之间的路程（米）；不在表里的返回 null */
export function routeMeters(from: string, to: string): number | null {
  const i = INDEX.get(from);
  const j = INDEX.get(to);
  if (i === undefined || j === undefined) return null;
  if (i === j) return 0;
  const a = Math.min(i, j);
  const b = Math.max(i, j);
  const n = ROUTE_ANCHORS.length;
  return ROUTE_METERS[a * n - (a * (a + 1)) / 2 + (b - a - 1)] ?? null;
}
